def decrypt_message(string):
    """Decrypts a given message using the same substitution cipher as encrypt_message"""
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    key = "fdnvyxktaslwjzogbpmheqricu"
    decrypted_message = ""
    for char in string:
        if char.lower() in key:
