import java.util.ArrayList;
import java.util.List;
public class SwearFilter {
    private List<String> swearWords;
    public SwearFilter() {
        swearWords = new ArrayList<>();
        // Add swear words to the list
        swearWords.add("fuck");
        swearWords.add("shit");
        swearWords.add("asshole");
        // and so on...
    }
    public boolean containsSwearWord(String message) {
        for (String swearWord : swearWords) {
            if (message.toLowerCase().contains(swearWord.toLowerCase())) {
                return true;
            }
        }
        return false;
