function throughTheFire(phrase) {
  const fire = ['🔥', '🔥', '🔥']; // fire-related data structure
  const words = phrase.split(' ');
  // loop through each word and add fire emojis to create the play on words
  const result = words.map((word) => {
    return word + ' ' + fire.join('');
  });
  return result.join(' 🔥🔥🔥 '); // add extra fire emojis between each word
}
```
