Sure, here's a sample C# code that can generate a palindrome phrase according to the requirements you specified:
```
using System;
using System.Collections.Generic;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        // Generate a random string of characters
        string randomString = GenerateRandomString();
        // Split the string into words
        string[] words = randomString.Split(' ');
        // Filter the words to only include nouns, adjectives, and verbs
        List<string> filteredWords = FilterWords(words);
        // Ensure that we have at least 8 filtered words
        while (filteredWords.Count < 8)
        {
            randomString = GenerateRandomString();
            words = randomString.Split(' ');
            filteredWords = FilterWords(words);
        }
        // Pick two synonyms for the first and last words
        string firstWord = filteredWords[0];
        string lastWord = filteredWords[filteredWords.Count - 1];
        List<string> synonyms = GetSynonyms(firstWord);
        synonyms = synonyms.Where(s => s != firstWord).ToList();
        string synonym = synonyms[new Random().Next(synonyms.Count)];
        filteredWords[0] = synonym;
        filteredWords[filteredWords.Count - 1] = firstWord;
        // Build the palindrome phrase
        string phrase = string.Join(" ", filteredWords);
        phrase += " " + GenerateSubordinateClause();
        phrase += " " + GenerateGerundPhrase();
        phrase += " " + string.Join(" ", filteredWords.Reverse());
        Console.WriteLine(phrase);
        Console.ReadLine();
    }
    static string GenerateRandomString()
    {
        string characters = "abcdefghijklmnopqrstuvwxyz";
        string punctuation = "!?";
        string randomString = "";
        Random random = new Random();
        // Generate a string of at least 12 alphabetic characters and 2 punctuation marks
        for (int i = 0; i < 12; i++)
        {
            randomString += characters[random.Next(characters.Length)];
        }
        for (int i = 0; i < 2; i++)
        {
            randomString += punctuation[random.Next(punctuation.Length)];
        }
        return randomString;
    }
    static List<string> FilterWords(string[] words)
    {
        List<string> filteredWords = new List<string>();
        foreach (string word in words)
        {
            if (WordNetEngine.IsNoun(word) || WordNetEngine.IsAdjective(word) || WordNetEngine.IsVerb(word))
            {
                filteredWords.Add(word);
            }
        }
        return filteredWords;
    }
    static List<string> GetSynonyms(string word)
    {
        List<string> synonyms = new List<string>();
        foreach (string synset in WordNetEngine.GetSynsets(word))
        {
            synonyms.AddRange(WordNetEngine.GetSynonyms(synset));
        }
        return synonyms;
    }
    static string GenerateSubordinateClause()
    {
        string[] clauses = { "who was", "which was", "that was" };
        return clauses[new Random().Next(clauses.Length)] + " " + GenerateRandomString();
    }
    static string GenerateGerundPhrase()
    {
        string[] verbs = { "running", "jumping", "swimming", "flying", "dancing" };
        string[] objects = { "in the park", "by the river", "under the moon", "in the rain", "on the beach" };
        return "while " + verbs[new Random().Next(verbs.Length)] + " " + objects[new Random().Next(objects.Length)];
    }
}
```
This code uses the WordNetEngine library to filter the words and find synonyms. You can download the WordNetEngine library from here: https://github.com/robertwilczynski/WordNetEngine
Note that the code may not always generate a palindrome phrase that meets all the requirements, as the randomness of the string generation and word filtering may not always produce a suitable phrase.

Here's Scala code that recursively calculates the sum of numbers in the array [2, 5, 8, 15, 7], ensuring that the sum is less than 20:
```
def recursiveSum(arr: Array[Int], sum: Int): Int = {
  if (arr.isEmpty || sum >= 20) {
    sum
  } else {
    recursiveSum(arr.tail, sum + arr.head)
  }
}
val arr = Array(2, 5, 8, 15, 7)
val sum = recursiveSum(arr, 0)
println(sum)
```
The `recursiveSum` function takes two parameters: the array `arr` and the current sum `sum`. If the array is empty or the sum is greater than or equal to 20, the function returns the current sum. Otherwise, it calls itself with the tail of the array (i.e., all elements except the first) and the current sum plus the first element of the array. 
In the main program, we define the array `arr` and call `recursiveSum` with `arr` and an initial sum of 0. The result is stored in `sum` and printed to the console.

