            ManagementBaseObject outParams = virtualMachine.InvokeMethod("CreateSystem", inParams, null);
            string vmPath = ((string[])outParams["CreatedSystemPaths"])[0];
            // Start the virtual machine
            ManagementObject vm = new ManagementObject(scope, new ManagementPath(vmPath), null);
            vm.Get();
            vm.InvokeMethod("RequestStateChange", new object[] { 2 });
            Console.WriteLine("Virtual machine started.");
            Console.ReadLine();
        }
    }
}

