        for (int i = 0; i < data.Length; i++)
        {
            sum += data[i];
        }
        return sum / data.Length;
    }
    static double CalculateStandardDeviation(double[] data, double mean)
    {
        double sum = 0;
        for (int i = 0; i < data.Length; i++)
        {
            sum += Math.Pow(data[i] - mean, 2);
        }
        return Math.Sqrt(sum / (data.Length - 1));
    }
    static double CalculateCorrelation(double[] data1, double mean1, double[] data2, double mean2, double sd1, double sd2)
    {
        double sum = 0;
        for (int i = 0; i < data1.Length; i++)
        {
            sum += ((data1[i] - mean1) / sd1) * ((data2[i] - mean2) / sd2);
        }
        return sum / (data1.Length - 1);
    }
}
