How can I calculate the geodesic distance in kilometers between Madrid, Spain (-3.6881, 40.4217) and New York, United States (-73.9714, 40.7507) using the Vincenty formula in C++? Here's an example code snippet in C++ that uses the Vincenty formula to calculate the distance between two points on a sphere:
#include <iostream>
#include <cmath>
using namespace std;
const double pi = acos(-1);
double distance(double lat1, double lon1, double lat2, double lon2){
    double a = 6378137, b = 6356752.3142, f = 1/298.257223563; //WGS-84 ellipsoid parameters
    double L = (lon2-lon1)*pi/180;
    double U1 = atan((1-f) * tan(lat1*pi/180));
    double U2 = atan((1-f) * tan(lat2*pi/180));
    double sinU1 = sin(U1), cosU1 = cos(U1);
    double sinU2 = sin(U2), cosU2 = cos(U2);
    double lambda = L, lambdaP, iterLimit = 100;
    double cosSqAlpha, sinSigma, cos2SigmaM, cosSigma, sigma, sinLambda, cosLambda;
    do {
        sinLambda = sin(lambda), cosLambda = cos(lambda);
        sinSigma = sqrt((cosU2*sinLambda) * (cosU2*sinLambda) +
            (cosU1*sinU2-sinU1*cosU2*cosLambda) * (cosU1*sinU2-sinU1*cosU2*cosLambda));
        if (sinSigma==0) return 0;
        cosSigma = sinU1*sinU2 + cosU1*cosU2*cosLambda;
        sigma = atan2(sinSigma, cosSigma);
        double sinAlpha = cosU1 * cosU2 * sinLambda / sinSigma;
        cosSqAlpha = 1 - sinAlpha*sinAlpha;
        cos2SigmaM = cosSigma - 2*sinU1*sinU2/cosSqAlpha;
        if (isnan(cos2SigmaM)) cos2SigmaM = 0;
        double C = f/16*cosSqAlpha*(4+f*(4-3*cosSqAlpha));
        lambdaP = lambda;
        lambda = L + (1-C) * f * sinAlpha *
            (sigma + C*sinSigma*(cos2SigmaM+C*cosSigma*(-1+2*cos2SigmaM*cos2SigmaM)));
    } while (fabs(lambda-lambdaP) > 1e-12 && --iterLimit>0);
    if (iterLimit==0) return NAN;
    double uSq = cosSqAlpha * (a*a - b*b) / (b*b);
    double A = 1 + uSq/16384*(4096+uSq*(-768+uSq*(320-175*uSq)));
    double B = uSq/1024 * (256+uSq*(-128+uSq*(74-47*uSq)));
    double deltaSigma = B*sinSigma*(cos2SigmaM+B/4*(cosSigma*(-1+2*cos2SigmaM*cos2SigmaM)-
        B/6*cos2SigmaM*(-3+4*sinSigma*sinSigma)*(-3+4*cos2SigmaM*cos2SigmaM)));
    double s = b*A*(sigma-deltaSigma);
    return s/1000; //kilometers
}
int main() {
    double lat1 = 40.4217, lon1 = -3.6881;
    double lat2 = 40.7507, lon2 = -73.9714;
    double dist = distance(lat1, lon1, lat2, lon2);
    cout << "The distance between Madrid, Spain and New York, United States is " << dist << " kilometers." << endl;
    return 0;
}

